/etc/nginx/nginx.conf.content:
worker_processes auto;
events {
    worker_connections 1024;
}
http {
    server {
        listen 80;
        server_name orders.internal;
        location / {
            proxy_pass http://127.0.0.1:3000;
        }
    }
}

